// Spike 12: FR-TEL-06 — "ツッコミ" telops generated by Azure OpenAI Structured Outputs.
// Checks: schema compliance, ≤14 width, only references existing captions, no invented numbers / long katakana names (H-07).
#:property PublishAot=false
#:package Azure.Identity@1.21.0
#:package OpenAI@2.14.0
using System.ClientModel.Primitives;
using System.Text.Json;
using System.Text.RegularExpressions;
using Azure.Identity;
using OpenAI;
using OpenAI.Chat;
#pragma warning disable OPENAI001

var root = Directory.GetCurrentDirectory();
int fails = 0;
void Check(bool ok, string msg) { Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {msg}"); if (!ok) fails++; }
using var tr = JsonDocument.Parse(File.ReadAllText(Path.Combine(root, "spikes", "out", "talk_transcript.json")));
var caps = tr.RootElement.GetProperty("phrases").EnumerateArray().Skip(8).Take(14).Select((p, i) => ($"c{i}", p.GetProperty("text").GetString()!)).ToList();
var source = string.Concat(caps.Select(c => c.Item2));

const string schema = """{"type":"object","additionalProperties":false,"required":["items"],"properties":{"items":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["caption_id","text"],"properties":{"caption_id":{"type":"string"},"text":{"type":"string"}}}}}}""";
var system = """
あなたは日本のバラエティ番組のテロップ担当です。字幕の流れを読み、ボケや意外な発言の直後に入る「ツッコミテロップ」を最大4個作ります。
規則:
- 各ツッコミは14字以内の短い口語（例:「いや多すぎ！」「そこ？」「言い方！」）
- caption_id は与えられた字幕のIDから選び、その字幕の直後に表示される
- 字幕に出てこない数字・固有名詞・商品名・人名を新しく書かない
- 人や集団を傷つける、侮辱する、差別的な内容は書かない。ツッコミの対象は「発言の内容」や「状況」にする
- 面白くなりそうな箇所が少なければ、個数を減らしてよい（0個でもよい）
""";
var user = "字幕:\n" + string.Join("\n", caps.Select(c => $"{c.Item1}: {c.Item2}"));
var client = new ChatClient("gpt-chat-latest", new BearerTokenPolicy(new DefaultAzureCredential(), "https://ai.azure.com/.default"),
    new OpenAIClientOptions { Endpoint = new Uri("https://videocreator-ai-40800.cognitiveservices.azure.com/openai/v1") });
int total = 0, ok = 0, tooLong = 0, badId = 0, invented = 0;
for (int trial = 0; trial < 4; trial++)
{
    var opts = new ChatCompletionOptions { ResponseFormat = ChatResponseFormat.CreateJsonSchemaFormat("tsukkomi", BinaryData.FromString(schema), jsonSchemaIsStrict: true) };
    ChatCompletion c = await client.CompleteChatAsync([new SystemChatMessage(system), new UserChatMessage(user)], opts);
    using var doc = JsonDocument.Parse(c.Content[0].Text);
    foreach (var it in doc.RootElement.GetProperty("items").EnumerateArray())
    {
        total++; var id = it.GetProperty("caption_id").GetString()!; var text = it.GetProperty("text").GetString()!;
        bool good = true;
        if (caps.All(x => x.Item1 != id)) { badId++; good = false; }
        if (text.Length > 14) { tooLong++; good = false; }
        var nums = Regex.Matches(text, @"[0-9０-９]+|[一二三四五六七八九十百千万]+").Select(m => m.Value).ToList();
        var kana = Regex.Matches(text, @"[ァ-ヴー]{4,}").Select(m => m.Value).ToList();
        if (nums.Any(n => !source.Contains(n)) || kana.Any(k => !source.Contains(k))) { invented++; good = false; }
        if (good) ok++;
        Console.WriteLine($"   trial {trial + 1}: {id} 「{text}」 {(good ? "" : "<- violates a rule")}");
    }
}
Check(total >= 4, $"{total} tsukkomi items over 4 trials");
Check(badId == 0, "all items reference an existing caption");
Console.WriteLine($"      rule violations before code-side filtering: too long {tooLong}, invented {invented}, bad id {badId}");
Check(ok >= total * 0.8, $"{ok}/{total} items satisfy every rule before filtering (the app filters the rest and marks all as 未承認)");
Console.WriteLine(fails == 0 ? "ALL PASS" : $"{fails} FAILED");
return fails;
